"""Write ``duration`` in canonical ISO 8601 form."""
d = duration
fields = (d.years, d.months, d.weeks, d.days, d.hours, d.minutes, d.seconds)
if any(not 0 <= value < float("inf") for value in fields):
    raise ValueError(f"cannot format duration: {d!r}")
date = "".join(
    f"{value}{unit}"
    for value, unit in ((d.years, "Y"), (d.months, "M"), (d.weeks, "W"), (d.days, "D"))
    if value
)
time = "".join(f"{value}{unit}" for value, unit in ((d.hours, "H"), (d.minutes, "M")) if value)
if d.seconds:
    if d.seconds == int(d.seconds):
        time += f"{int(d.seconds)}S"
    else:
        # Shortest round-tripping digits, never in exponent notation.
        time += f"{Decimal(repr(float(d.seconds))):f}S"
if not date and not time:
    return "PT0S"
return "P" + date + ("T" + time if time else "")

